// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Makroekonomi: milli gelir, büyüme, işsizlik (kolay).
const ozEconomics8Kolay = <(String, String, List<String>, String)>[
  ('Devletin emeklilere ödediği aylıklar GSYH hesabında kamu harcaması olarak neden yer almaz?', 'Karşılığında o dönemde bir mal ya da hizmet üretilmediği için', ['Emekli aylıkları vergiden muaf tutulduğu için', 'Aylıklar bir sonraki yılın hesabına aktarıldığı için', 'Sosyal güvenlik kurumları kamu sektörünün bir parçası sayılmadığı için'], 'Emekli aylığı bir transfer ödemesidir; gelir el değiştirir ama karşılığında cari üretim yoktur. Bu yüzden GSYH\'nin kamu harcaması kalemine girmez.'),
  ('Bir yatırımcının borsadan bir şirketin hisse senetlerini satın alması, harcama yöntemiyle hesaplanan GSYH\'nin yatırım kalemini nasıl etkiler?', 'Doğrudan etkilemez; bu bir finansal varlık el değişimidir', ['Yatırım kalemini hisse tutarı kadar artırır', 'Yatırım kalemini hisse tutarı kadar azaltır', 'Tüketim kalemine aktarılarak GSYH\'yi hisse tutarı kadar artırır'], 'Makroekonomide yatırım, makine, bina ve stok gibi yeni sermaye mallarına yapılan harcamadır. Hisse alımı mevcut bir varlığın sahibini değiştirir, yeni üretim yaratmaz.'),
  ('GSYH ile ilgili olarak aşağıdaki ifadelerden hangisi doğrudur?', 'Belirli bir dönemde ölçülen bir akım değişkendir', ['Belirli bir anda, örneğin yıl sonunda ölçülen bir stok değişkendir', 'Bir ülkenin toplam servetini gösterir', 'Yalnızca sanayi üretimini kapsar'], 'GSYH bir yıl ya da bir çeyrek gibi bir dönem boyunca yapılan üretimi ölçer, bu yüzden akımdır. Servet ise belirli bir andaki birikimdir ve stoktur.'),
  ('Yeni yapılan bir konutun bir hanehalkı tarafından satın alınması, harcama yöntemiyle GSYH hesabında hangi kalemde yer alır?', 'Yatırım', ['Tüketim', 'Kamu harcaması', 'Net ihracat'], 'Ulusal hesaplarda yeni konut alımı, uzun yıllar hizmet veren bir varlık olduğu için tüketim değil, konut yatırımı sayılır.'),
  ('Bir hanehalkının yeni bir buzdolabı satın alması harcama yöntemiyle GSYH hesaplanırken hangi gruba girer?', 'Dayanıklı tüketim harcaması', ['Sabit sermaye yatırımı', 'Stok yatırımı', 'Ara mal harcaması'], 'Buzdolabı uzun ömürlü olsa da hanehalkının aldığı mallar tüketim sayılır. Uzun ömürlü olanlar dayanıklı tüketim malı olarak ayrıca gruplanır.'),
  ('Bir üretim zincirindeki bütün aşamaların yarattığı katma değerler toplandığında elde edilen tutar neye eşittir?', 'Zincirin sonunda satılan nihai malın değerine', ['Zincirdeki bütün aşamalarda yapılan satışların toplamına', 'İlk aşamadaki hammaddenin değerine', 'Nihai malın değerinin iki katına'], 'Her aşamanın katma değeri satış değeri eksi aldığı girdidir. Bu farklar toplandığında ara mallar birbirini götürür ve nihai malın değeri kalır.'),
  ('Türkiye\'de yerleşik bir Alman şirketinin İzmir\'deki fabrikasında üretilen makineler hangi ülkenin GSYH\'sine katılır?', 'Türkiye\'nin', ['Almanya\'nın', 'Her iki ülkenin yarı yarıya', 'Hiçbir ülkenin'], 'GSYH coğrafi sınırları esas alır: Türkiye sınırları içinde yapılan üretim, şirketin sahibi kim olursa olsun Türkiye\'nin GSYH\'sine girer.'),
  ('GSYH\'nin gelir yöntemiyle hesaplanmasında üretim faktörlerine yapılan hangi dört tür ödeme toplanır?', 'Ücret, rant, faiz ve kâr', ['Tüketim, yatırım, kamu harcaması ve net ihracat', 'Vergi, sübvansiyon, transfer ve amortisman', 'Ücret, ikramiye, emekli aylığı ve kira yardımı'], 'Gelir yöntemi, üretimden doğan gelirleri toplar: emeğe ücret, toprağa rant, sermayeye faiz, girişimciye kâr. Harcama kalemleri ise başka bir yöntemin konusudur.'),
  ('Bir ekonomide bir yılda ücretler 600, rantlar 50, faizler 80 ve kârlar 270 milyar liradır. Gelir yöntemine göre faktör maliyetiyle milli gelir kaç milyar liradır?', '1.000', ['920', '950', '1.270'], 'Faktör gelirleri toplanır: 600 + 50 + 80 + 270 = 1.000 milyar lira.'),
  ('Gayrisafi yurt içi hasıladan (GSYH) hangi kalem düşülünce safi (net) yurt içi hasılaya ulaşılır?', 'Sermaye tüketimi', ['Dolaylı vergiler', 'Transfer ödemeleri', 'Net ihracat'], 'Üretim sırasında makine ve binaların aşınan kısmı amortisman olarak ayrılır. GSYH\'den amortisman düşülünce net yurt içi hasıla elde edilir.'),
  ('Kullanılabilir (harcanabilir) gelir hangi iki kullanım arasında paylaştırılır?', 'Tüketim ve tasarruf', ['Yatırım ve ithalat', 'Vergi ve transfer', 'Ücret ve kâr'], 'Hanehalkı, vergiler ödendikten sonra elinde kalan geliri ya harcar (tüketim) ya da harcamaz (tasarruf).'),
  ('Çoğu ülkede harcama yöntemiyle hesaplanan GSYH\'nin en büyük payını genellikle hangi bileşen oluşturur?', 'Hanehalkı tüketim harcamaları', ['Kamu yatırımları', 'Stok değişimi', 'Net ihracat'], 'Gelişmiş ve gelişmekte olan ekonomilerin büyük çoğunluğunda hanehalkı tüketimi GSYH\'nin yarısından fazlasını oluşturur.'),
  ('Harcama yöntemiyle GSYH hesaplanırken yatırım kalemi hangi alt bileşenlerden oluşur?', 'Sabit sermaye yatırımı ve stok değişimi', ['Hisse senedi ve tahvil alımları', 'Kamu transferleri ve sübvansiyonlar', 'Dayanıklı ve dayanıksız tüketim mallarına yapılan harcamalar'], 'Ulusal hesaplarda yatırım; makine, teçhizat, bina ve konut gibi sabit sermaye oluşumu ile stoklardaki değişimden oluşur. Finansal varlık alımları yatırım sayılmaz.'),
  ('Devletin bir yol yapımı için müteahhide ödediği bedel ile işsizlere ödediği işsizlik ödeneği arasındaki temel fark, GSYH hesabı açısından hangisidir?', 'Yol bedeli GSYH\'ye girer, işsizlik ödeneği girmez', ['İkisi de GSYH\'ye kamu harcaması olarak girer', 'İşsizlik ödeneği GSYH\'ye kamu harcaması olarak girer, yol bedeli girmez', 'İkisi de GSYH\'ye girmez'], 'Yol yapımı karşılığında yeni bir mal üretilmiştir; bu kamu harcamasıdır. İşsizlik ödeneği ise karşılıksız bir transferdir, cari üretimi göstermez.'),
  ('Bir ülkenin net ihracatının sıfır olması, o ülkenin dış ticareti hakkında ne söyler?', 'İhracat değeri ithalat değerine eşittir', ['Ülke hiç dış ticaret yapmamaktadır', 'Ülkenin ihracatı ve ithalatı yasaklanmıştır', 'İthalat ihracatın iki katıdır'], 'Net ihracat ihracat eksi ithalattır. Sıfır olması ticaretin olmadığını değil, alım ve satımın birbirine eşit olduğunu gösterir.'),
  ('Baz yılında bir ülkenin nominal GSYH\'si ile reel GSYH\'si arasındaki ilişki nedir?', 'Birbirine eşittir', ['Reel GSYH her zaman iki kat büyüktür', 'Nominal GSYH sıfır kabul edilir', 'Reel GSYH hesaplanamaz'], 'Reel GSYH baz yılı fiyatlarıyla hesaplanır. Baz yılında cari fiyatlar ile baz fiyatlar aynı olduğundan iki büyüklük eşittir ve deflatör 100 çıkar.'),
  ('Bir ülkenin nominal GSYH\'si 2.400 milyar lira, GSYH deflatörü 150\'dir. Reel GSYH kaç milyar liradır?', '1.600', ['3.600', '2.250', '1.500'], 'Reel GSYH = nominal GSYH / (deflatör / 100) = 2.400 / 1,5 = 1.600 milyar lira.'),
  ('Bir ülkenin GSYH\'si 900 milyar dolar, nüfusu 60 milyondur. Kişi başına GSYH kaç dolardır?', '15.000', ['1.500', '54.000', '150.000'], 'Kişi başı GSYH = 900.000.000.000 / 60.000.000 = 15.000 dolar.'),
  ('Kişi başına GSYH bir ülkenin yaşam standardı hakkında fikir verse de aşağıdakilerden hangisini tek başına göstermez?', 'Gelirin nüfus arasında nasıl paylaşıldığını', ['Toplam üretimin nüfusa oranını', 'Ortalama üretim düzeyini', 'Ülkeler arasında ortalama gelir sıralamasını'], 'Kişi başı GSYH bir ortalamadır. Aynı ortalamaya sahip iki ülkeden birinde gelir çok eşit, diğerinde çok eşitsiz dağılmış olabilir.'),
  ('Bir ülkede çalışanların haftalık çalışma süresi 50 saatten 40 saate inerken GSYH aynı kalmıştır. GSYH\'nin bu değişimi refah açısından gösterememesinin nedeni hangisidir?', 'Boş zamanın değeri GSYH\'de ölçülmez', ['GSYH yalnızca tarımı kapsar', 'GSYH çalışma saatlerine göre otomatik düzeltilir', 'Boş zaman yatırım olarak sayılır'], 'Aynı üretim daha az çalışmayla yapılıyorsa insanlar boş zaman kazanmış ve refahları artmıştır. GSYH bu kazancı yansıtmaz.'),
  ('Bir ülkede ekonomik faaliyetlerin önemli bir kısmının kayıt dışı yürütülmesi resmî istatistikleri nasıl etkiler?', 'Resmî GSYH ve kişi başı gelir olduğundan düşük görünür', ['Resmî GSYH olduğundan yüksek görünür', 'İşsizlik oranı mutlaka sıfıra iner', 'Enflasyon oranı ölçülemez hâle gelir ve hiç yayımlanamaz'], 'Kayıt dışı üretim istatistiklere girmediği için ülkenin üretimi ve kişi başı geliri gerçekte olduğundan küçük ölçülür.'),
  ('Kayıt dışı çalışan bir işçinin karşılaştığı en önemli dezavantaj hangisidir?', 'Emeklilik ve sağlık güvencesinden yoksun kalması', ['Gelir vergisini iki kez ödemesi', 'Ücretinin döviz cinsinden ve yalnızca yıl sonunda ödenmesi', 'Hiçbir koşulda işten çıkarılamaması'], 'Sosyal güvenlik kaydı olmayan işçi için prim ödenmez; bu nedenle emeklilik hakkı birikmez, iş kazası ve sağlık güvencesi de yoktur.'),
  ('Döngüsel akım modelinde tasarruf, vergiler ve ithalat ortak olarak hangi adla anılır?', 'Sızıntılar', ['Enjeksiyonlar', 'Transferler', 'Ara mallar'], 'Bu üç kalem, hanehalklarının elde ettiği gelirin yurt içi mallara yapılan harcama akımından çekilen kısımlarıdır; bu yüzden sızıntı (kaçak) olarak adlandırılır.'),
  ('Döngüsel akım modelinde aşağıdakilerden hangisi bir enjeksiyon (ekleme) örneğidir?', 'Yabancıların yurt içi mallara yaptığı harcama', ['Hanehalklarının her ay bankaya yatırdığı tasarruflar', 'Devletin topladığı gelir vergisi', 'Yurt dışından alınan mallar'], 'Enjeksiyonlar yatırım, kamu harcaması ve ihracattır; harcama akımına dışarıdan eklenen kalemlerdir. İhracat, yabancıların yurt içi üretime harcamasıdır.'),
  ('Döngüsel akım modeli iki sektörlüden dört sektörlüye genişletilirken hanehalkı ve firmalara hangi iki sektör eklenir?', 'Devlet ve dış dünya', ['Bankalar ve borsa', 'Tarım ve sanayi', 'İşçiler ve işverenler'], 'İki sektörlü model yalnızca hanehalkları ve firmalardan oluşur. Üç sektörlü modele devlet, dört sektörlü modele dış dünya eklenir.'),
  ('Kapalı bir ekonomide GSYH 1.000, tüketim 650 ve kamu harcaması 200 milyar liradır. Ulusal tasarruf kaç milyar liradır?', '150', ['350', '200', '800'], 'Kapalı ekonomide ulusal tasarruf = Y − C − G = 1.000 − 650 − 200 = 150 milyar liradır ve yatırıma eşittir.'),
  ('Ulusal tasarruf hangi iki bileşenin toplamıdır?', 'Özel tasarruf ve kamu tasarrufu', ['Yatırım ve tüketim', 'İhracat ve ithalat', 'Ücretler ve kârlar'], 'Özel tasarruf Y − T − C, kamu tasarrufu T − G\'dir. Toplamları ulusal tasarrufu, yani Y − C − G\'yi verir.'),
  ('Bir devletin vergi gelirleri 400, harcamaları 470 milyar liradır. Ulusal tasarruf açısından kamu tasarrufu için ne söylenir?', '−70 milyar lira, yani negatiftir', ['70 milyar lira, yani pozitiftir', '870 milyar liradır', 'Sıfırdır, çünkü vergiler tasarruf sayılmaz'], 'Kamu tasarrufu T − G = 400 − 470 = −70\'tir. Bütçe açığı, kamu kesiminin negatif tasarruf yaptığı ve ulusal tasarrufu azalttığı anlamına gelir.'),
  ('Bir ekonomide tüketim fonksiyonu C = 100 + 0,75Yd biçimindedir. Kullanılabilir gelir (Yd) 800 milyar lira olduğunda tüketim kaç milyar liradır?', '700', ['600', '750', '900'], 'C = 100 + 0,75 × 800 = 100 + 600 = 700 milyar lira.'),
  ('Marjinal tüketim eğilimi ile marjinal tasarruf eğiliminin toplamı (vergisiz bir modelde) neye eşittir?', '1', ['0', 'Ortalama tüketim eğilimine', 'Çarpanın değerine'], 'Ek gelirin her lirası ya tüketilir ya tasarruf edilir. Bu yüzden MTE + MTasE = 1\'dir.'),
  ('Geliri 500 bin lira olan bir hane bunun 450 bin lirasını tüketmektedir. Bu hanenin ortalama tüketim eğilimi kaçtır?', '0,9', ['0,1', '1,1', '0,45'], 'Ortalama tüketim eğilimi = C / Y = 450 / 500 = 0,9\'dur.'),
  ('Keynes\'in \'temel psikolojik yasa\' olarak adlandırdığı tüketim davranışı hangisidir?', 'Gelir arttıkça tüketim de artar, ama gelirdeki artıştan daha az', ['Gelir arttıkça tüketim de her zaman tam olarak aynı oranda artar', 'Gelir arttıkça tüketim azalır', 'Tüketim gelirden tamamen bağımsızdır'], 'Keynes\'e göre marjinal tüketim eğilimi 0 ile 1 arasındadır: ek gelirin bir kısmı harcanır, bir kısmı tasarruf edilir.'),
  ('Keynesyen tüketim fonksiyonunda otonom tüketim neyi ifade eder?', 'Gelir sıfır olsa bile yapılan zorunlu tüketimi', ['Gelirin tamamen tasarruf edilen bölümünü', 'Devletin hanehalkları adına yaptığı tüketim harcamalarını', 'Yalnızca ithal malların tüketimini'], 'C = a + bY fonksiyonundaki a terimi, gelirden bağımsız tüketimdir. Gelir yokken bu tüketim birikimlerden ya da borçlanmayla karşılanır.'),
  ('Bir hanehalkının yıllık geliri, tüketiminden küçük olduğunda hanehalkı için hangi durum söz konusudur?', 'Negatif tasarruf yapmaktadır', ['Marjinal tasarruf eğilimi 1\'dir', 'Otonom tüketimi sıfırdır', 'Pozitif net yatırım yapmaktadır'], 'Tasarruf gelir eksi tüketimdir. Tüketim gelirden büyükse fark birikimlerden ya da borçla karşılanır; bu negatif tasarruftur.'),
  ('Keynes\'e göre bir firmanın yeni bir yatırım yapıp yapmayacağı, sermayenin marjinal etkinliğinin hangi büyüklükle karşılaştırılmasına bağlıdır?', 'Faiz oranı', ['Enflasyon oranı', 'İşsizlik oranı', 'Vergi oranı'], 'Yatırımın beklenen getiri oranı (sermayenin marjinal etkinliği) faiz oranından yüksekse yatırım kârlıdır; düşükse firma parasını faizle değerlendirmeyi yeğler.'),
  ('Bir ekonomide tam istihdam geliri 1.000, denge geliri 800 milyar lira ve çarpan 5\'tir. Deflasyonist (durgunluk) açık kaç milyar liradır?', '40', ['200', '160', '1.000'], 'Gelir açığı 200 milyar liradır. Bu açığı kapatmak için gereken ek harcama 200 / 5 = 40 milyar liradır.'),
  ('Keynesyen modelde \'enflasyonist açık\' kavramı hangi durumu anlatır?', 'Tam istihdam gelir düzeyinde toplam harcamanın üretimi aşması', ['İşsizlik oranının doğal oranın üzerine çıkması', 'Kamu bütçesinin açık vermesi', 'Toplam harcamanın tam istihdam düzeyindeki üretimin gerisinde kalması'], 'Tam istihdamda üretim artırılamadığından harcama fazlası fiyatları yükseltir. Harcamanın eksik kaldığı durum ise deflasyonist açıktır.'),
  ('Deflasyonist açığın bulunduğu bir ekonomide Keynesyen yaklaşıma göre hangi durum gözlenir?', 'Toplam talep yetersizliği nedeniyle işsizlik yüksektir', ['Fiyatlar hızla yükselmekte ve fabrikalarda kapasite sınırı aşılmaktadır', 'Ekonomi tam istihdamın üzerinde üretim yapmaktadır', 'Tasarruflar yatırımları sürekli aşamaz'], 'Toplam harcamanın tam istihdam üretimini satın almaya yetmemesi, üretimin potansiyelin altında kalmasına ve işsizliğe yol açar.'),
  ('Basit Keynesyen modelde denge, hangi koşul sağlandığında oluşur?', 'Planlanan toplam harcama üretime eşitlendiğinde', ['Gerçekleşen yatırım sıfır olduğunda', 'Bütün gelir tüketildiğinde ve tasarruf yapılmadığında', 'İşsizlik oranı sıfıra indiğinde'], 'Planlanan harcama üretime eşitse firmaların stokları beklenmedik biçimde değişmez ve üretimi değiştirme isteği oluşmaz. Bu denge tam istihdamın altında da olabilir.'),
  ('Bir ülkenin en büyük ihracat pazarları derin bir resesyona girerse bu ülkenin toplam talep eğrisine kısa dönemde ne olur?', 'Sola kayar', ['Sağa kayar', 'Dikey hâle gelir', 'Değişmez; yalnızca arz eğrisi kayar'], 'Yabancı gelirler düşünce ülkenin ihraç mallarına talep azalır. Net ihracat her fiyat düzeyinde düştüğünden toplam talep sola kayar.'),
  ('Hanehalklarının geleceğe ilişkin iyimserliğinin artması (tüketici güveninin yükselmesi) toplam talep-toplam arz modelinde kısa dönemde hangi sonucu doğurur?', 'Üretim ve fiyat düzeyi birlikte artar', ['Üretim artar, fiyat düzeyi düşer', 'Üretim azalır, fiyat düzeyi artar', 'Üretim ve fiyat düzeyi birlikte azalır'], 'Güven artışı tüketimi artırarak toplam talebi sağa kaydırır. Pozitif eğimli kısa dönem arz eğrisi boyunca hem üretim hem fiyatlar yükselir.'),
  ('Dünya petrol fiyatlarının kalıcı biçimde düşmesi gibi olumlu bir arz şoku toplam talep-toplam arz modelinde kısa dönemde hangi sonucu doğurur?', 'Fiyat düzeyi düşer, üretim artar', ['Fiyat düzeyi ve üretim birlikte düşer', 'Fiyat düzeyi artar, üretim azalır', 'Fiyat düzeyi ve üretim birlikte artar'], 'Maliyetlerin düşmesi kısa dönem arz eğrisini sağa kaydırır; yeni dengede daha düşük fiyat düzeyinde daha fazla üretim yapılır.'),
  ('Toplam talep-toplam arz modelinde fiyat düzeyinin bir göstergesi olarak genellikle hangi büyüklük kullanılır?', 'GSYH deflatörü ya da tüketici fiyat endeksi', ['İşsizlik oranı', 'Politika faizi', 'Kişi başı GSYH ve büyüme hızı ortalaması'], 'Modelin dikey ekseni ekonomideki genel fiyat düzeyini gösterir; bu düzey uygulamada deflatör ya da TÜFE gibi endekslerle ölçülür.'),
  ('Bir konjonktür dalgasının evreleri, genişlemeden başlanarak doğru sırayla hangisidir?', 'Genişleme, tepe, daralma, dip', ['Genişleme, dip, daralma, tepe', 'Tepe, genişleme, dip, daralma', 'Daralma, tepe, genişleme, dip'], 'Ekonomi genişleme evresinde büyür, tepe noktasında büyüme durur, daralma evresinde küçülür ve dip noktasında yeniden genişlemeye geçer.'),
  ('Konjonktürde \'dip noktası\' hangi anı ifade eder?', 'Daralmanın bitip genişlemenin başladığı anı', ['Enflasyonun en yüksek olduğu anı', 'Genişlemenin sona erip daralmanın başladığı anı', 'Bütçe açığının sıfırlandığı ve kamu borcunun azaldığı anı'], 'Dip, ekonomik faaliyetin en düşük düzeye indiği ve toparlanmanın başladığı dönüm noktasıdır. Genişlemenin bittiği nokta ise tepedir.'),
  ('Medyada sıkça kullanılan \'teknik resesyon\' tanımı hangisidir?', 'Reel GSYH\'nin art arda iki çeyrek azalması', ['İşsizlik oranının iki puan artması', 'Enflasyonun iki çeyrek boyunca yüzde 10\'u aşması', 'Nominal GSYH\'nin bir yıl boyunca hiç değişmeden aynı kalması'], 'Pratikte yaygın kural, mevsimsellikten arındırılmış reel GSYH\'nin üst üste iki çeyrek önceki çeyreğe göre küçülmesidir.'),
  ('ABD\'de resesyonların başlangıç ve bitiş tarihlerini resmî olmasa da genel kabul gören biçimde belirleyen kuruluş hangisidir?', 'Ulusal Ekonomik Araştırma Bürosu', ['ABD Hazine Bakanlığı', 'Uluslararası Para Fonu', 'ABD Merkez Bankası Açık Piyasa Komitesi'], 'Özel ve kâr amacı gütmeyen NBER\'in iş çevrimi tarihleme komitesi, ABD\'de resesyonların tepe ve dip tarihlerini belirler.'),
  ('Resesyon ile depresyon arasındaki fark en iyi nasıl açıklanır?', 'Depresyon, çok daha derin ve uzun süren bir daralmadır', ['Depresyon yalnızca tarım sektöründeki daralmadır', 'Resesyon fiyatların, depresyon miktarların düşmesidir', 'Depresyon, yalnızca bir çeyrek süren hafif bir küçülme olarak tanımlanır'], 'Kesin bir sayısal sınır olmasa da depresyon, 1930\'lardaki Büyük Buhran gibi üretim ve istihdamda çok büyük ve yıllarca süren kayıpları anlatır.'),
  ('Ekonominin sert biçimde daralıp kısa sürede yine hızla eski düzeyine dönmesi hangi toparlanma biçimiyle anlatılır?', 'V tipi', ['L tipi', 'W tipi', 'U tipi'], 'V harfi, keskin bir düşüşün ardından aynı hızda bir yükselişi simgeler. U tipinde dip dönemi daha uzun sürer.'),
  ('Bir ekonominin kısa bir toparlanmanın ardından yeniden daralmaya girmesiyle oluşan \'çift dipli resesyon\' hangi harfle simgelenir?', 'W', ['V', 'L', 'U'], 'W harfi iki ayrı dibi gösterir: ilk düşüş, kısa bir toparlanma, ikinci düşüş ve ardından kalıcı toparlanma.'),
  ('Ekonomik dalgalanmalarda işsizlik oranı için hangisi doğrudur?', 'Konjonktür karşıtı hareket eder', ['Konjonktürle aynı yönde hareket eder', 'Konjonktürden tamamen bağımsızdır', 'Yalnızca tepe noktasında yükselir ve dipte sabit kalır'], 'Genişleme dönemlerinde istihdam artar ve işsizlik düşer; daralmada ise işsizlik yükselir. Bu yüzden işsizlik konjonktür karşıtıdır.'),
  ('Yeni konut inşaat izinlerinin sayısı, ekonomik faaliyeti birkaç ay önceden haber verdiği için hangi gösterge grubunda yer alır?', 'Öncü göstergeler', ['Gecikmeli göstergeler', 'Eşzamanlı göstergeler', 'Yapısal göstergeler'], 'İnşaat izinleri gelecekteki inşaat faaliyetini ve ilgili harcamaları önceden yansıttığı için konjonktürün yönünü erken gösterir.'),
  ('Tüketim, yatırım ve istihdam gibi değişkenlerin GSYH ile aynı yönde dalgalanmasını anlatan terim hangisidir?', 'Konjonktür yanlısı (prosiklik)', ['Konjonktür karşıtı', 'Asiklik (konjonktürden bağımsız)', 'Mevsimsel (yıllık dalgalanma)'], 'Ekonomi büyürken artan, daralırken azalan değişkenler konjonktür yanlısıdır. İşsizlik gibi ters hareket edenler ise konjonktür karşıtıdır.'),
  ('Ekonomide \'işgücü\' büyüklüğü hangi iki grubun toplamıdır?', 'İstihdam edilenler ve işsizler', ['İşsizler ve emekliler', 'Çalışma çağındaki nüfus ve çocuklar', 'İstihdam edilenler ve işgücüne dâhil olmayanlar'], 'İşgücü, çalışan ya da aktif olarak iş arayan kişilerden oluşur. İş aramayan öğrenci, emekli ve ev işleriyle meşgul olanlar işgücü dışındadır.'),
  ('Üniversitede tam zamanlı okuyan, hiç çalışmayan ve iş de aramayan 20 yaşındaki bir öğrenci işgücü istatistiklerinde nasıl sınıflanır?', 'İşgücüne dâhil olmayanlar arasında', ['İşsizler arasında', 'İstihdamda, eğitimde olduğu için', 'Eksik istihdam edilenler arasında sayılır'], 'İş aramayan ve çalışmayan kişiler işsiz sayılmaz; işgücünün dışında kalır. Bu yüzden öğrenciler işsizlik oranını doğrudan etkilemez.'),
  ('Türkiye\'de resmî işsizlik oranı hangi kaynaktan elde edilir?', 'TÜİK\'in Hanehalkı İşgücü Araştırması\'ndan', ['İŞKUR\'a kayıtlı iş arayanların sayısından', 'SGK\'nın aylık prim bildirgelerinden', 'Gelir İdaresi\'nin vergi kayıtlarından ve beyannamelerden'], 'Resmî işsizlik oranı, uluslararası tanımlara uygun bir hanehalkı anketiyle hesaplanır. İŞKUR\'a kayıtlı işsiz sayısı ayrı bir idari veridir ve kapsamı farklıdır.'),
  ('Çalışma çağındaki nüfusu 80 milyon olan bir ülkede 36 milyon kişi istihdamda, 4 milyon kişi işsizdir. İstihdam oranı yüzde kaçtır?', '45', ['50', '90', '40'], 'İstihdam oranı = istihdam / çalışma çağındaki nüfus = 36 / 80 = 0,45, yani yüzde 45\'tir. Yüzde 50 işgücüne katılma oranı, yüzde 10 ise işsizlik oranıdır.'),
  ('Türkiye\'de kadınların işgücüne katılma oranı erkeklerinkiyle karşılaştırıldığında genel olarak nasıldır?', 'Belirgin biçimde düşüktür', ['Belirgin biçimde yüksektir', 'Her yıl tam olarak eşittir', 'Yalnızca kırsal kesimde ölçülebildiği için karşılaştırılamaz'], 'TÜİK verilerinde kadınların işgücüne katılım oranı uzun yıllardır erkeklerinkinin yaklaşık yarısı düzeyindedir; bu, Türkiye işgücü piyasasının yapısal bir özelliğidir.'),
  ('Uluslararası istatistiklerde \'uzun süreli işsiz\' kavramı hangi kişileri tanımlar?', 'Bir yıl ya da daha uzun süredir iş arayan işsizleri', ['İki haftadan uzun süredir işsiz olanları', 'Hiç çalışmamış olan bütün gençleri', 'Emekliliğe bir yıldan az süre kalmış ve işsiz olan çalışanları'], 'ILO ve Eurostat uzun süreli işsizliği 12 ay ya da daha uzun süredir iş arayan işsizler olarak tanımlar; bu grup becerilerini yitirme riski taşır.'),
  ('Genç işsizlik oranı uluslararası istatistiklerde genellikle hangi yaş grubu için hesaplanır?', '15-24 yaş', ['18-35 yaş', '12-18 yaş', '25-40 yaş arasındaki yetişkinler'], 'TÜİK, ILO ve Eurostat genç işsizlik oranını 15-24 yaş arasındaki işgücü için yayımlar.'),
  ('Ne eğitimde ne de istihdamda bulunan gençleri tanımlamak için kullanılan uluslararası kısaltma hangisidir?', 'NEET', ['NAIRU', 'OECD', 'PISA'], 'NEET, \'Not in Education, Employment or Training\' ifadesinin kısaltmasıdır; ne eğitim ne istihdam ne de mesleki eğitimde olan gençleri kapsar.'),
  ('Klasik iktisatçılara göre piyasada geçerli olan ücretle çalışmak istemeyen kişilerin işsizliği nasıl nitelendirilir?', 'Gönüllü işsizlik', ['Gönülsüz işsizlik', 'Konjonktürel işsizlik', 'Gizli işsizlik'], 'Klasik görüşe göre ücretler esnekse çalışmak isteyen herkes iş bulur. Bu ücretle çalışmayı kabul etmeyenlerin işsizliği gönüllüdür.'),
  ('Bir ekonomide gerçekleşen işsizlik oranı yüzde 11, doğal işsizlik oranı yüzde 7 olarak tahmin edilmektedir. Konjonktürel işsizlik kaç puandır?', '4', ['18', '7', '11'], 'Konjonktürel işsizlik, gerçekleşen oranın doğal oranı aşan kısmıdır: 11 − 7 = 4 puan.'),
  ('İşsizliğin ekonomi açısından en doğrudan maliyeti hangisidir?', 'Üretilebilecekken üretilmeyen mal ve hizmetler', ['Fiyatların sürekli düşmesi', 'İhracatın kendiliğinden artması', 'Tasarrufların ve yatırımların hızla yükselmesi'], 'İşsiz kalan emek, bir daha geri getirilemeyecek bir üretim kaybı demektir; bu kayıp Okun yasasıyla da ölçülmeye çalışılır.'),
  ('İşsizlik ile üretim arasındaki ampirik ilişkiyi ilk kez 1962\'de ortaya koyan ve bu ilişkiye adını veren iktisatçı kimdir?', 'Arthur Okun', ['Alban Phillips', 'Robert Lucas', 'Nicholas Kaldor'], 'Kennedy ve Johnson dönemlerinde danışmanlık yapan Arthur Okun, işsizlikteki değişmelerle GSYH arasındaki düzenli ilişkiyi 1962\'de yayımlamıştır.'),
  ('Okun yasasına göre bir ekonomi tam olarak potansiyel büyüme hızında büyürse işsizlik oranı için ne beklenir?', 'Yaklaşık olarak sabit kalır', ['Sıfıra iner', 'Hızla yükselir', 'Potansiyel büyüme hızına eşitlenir ve orada kalır'], 'İşgücü ve verimlilik artışı potansiyel büyümeyi belirler. Üretim bu hızda artarsa yeni katılanlar iş bulur, işsizlik oranı değişmez.'),
  ('Arthur Okun\'un yaygınlaştırdığı, enflasyon oranı ile işsizlik oranının toplanmasıyla hesaplanan göstergeye ne ad verilir?', 'Sefalet endeksi', ['Gini endeksi', 'Herfindahl endeksi', 'Tüketici güven endeksi'], 'Sefalet (misery) endeksi, iki temel makroekonomik sorunu tek sayıda birleştirir; değer yükseldikçe ekonomik koşulların kötüleştiği kabul edilir.'),
  ('Bir ülkede yıllık enflasyon yüzde 9, işsizlik oranı yüzde 8\'dir. Bu ülkenin sefalet endeksi kaçtır?', '17', ['1', '72', '8,5'], 'Sefalet endeksi enflasyon ile işsizlik oranının toplamıdır: 9 + 8 = 17.'),
  ('Bir resesyonun ardından GSYH yeniden büyümeye başladığı hâlde istihdamın uzun süre artmamasına ne ad verilir?', 'İstihdamsız büyüme', ['Stagflasyon', 'Aşırı ısınma', 'Deflasyon sarmalı ve borç tuzağı'], 'Firmalar toparlanmanın ilk evresinde mevcut çalışanlarla verimliliği artırarak üretimi yükseltebilir; bu nedenle istihdam büyümeyi gecikmeli izler.'),
  ('Bir ülkenin reel GSYH\'si bir yılda 800 milyar liradan 840 milyar liraya çıkmıştır. Reel büyüme oranı yüzde kaçtır?', '5', ['4', '40', '4,8'], 'Büyüme oranı (840 − 800) / 800 = 40 / 800 = 0,05, yani yüzde 5\'tir.'),
  ('Bir ülkede yıllık GSYH 1.200 milyar lira, toplam fiilî çalışma süresi 60 milyar saattir. Saat başına emek verimliliği kaç liradır?', '20', ['50', '72', '0,05'], 'Saat başına verimlilik = GSYH / toplam çalışma saati = 1.200 / 60 = 20 liradır.'),
  ('Bir ekonomide reel GSYH yüzde 3, toplam çalışma saati yüzde 1 artmıştır. Saat başına emek verimliliği yaklaşık yüzde kaç artmıştır?', '2', ['3', '4', '1'], 'Verimlilik büyümesi yaklaşık olarak üretim büyümesi ile çalışma saati büyümesinin farkıdır: 3 − 1 = yüzde 2.'),
  ('Mülkiyet haklarının güvencede olmadığı, el koyma riskinin yüksek olduğu bir ülkede uzun dönem büyümenin zayıf kalmasının temel nedeni hangisidir?', 'Girişimcilerin yatırımlarının getirisini elde edemeyeceklerinden korkması', ['Nüfusun hızla azalması ve işgücünün tükenmesi', 'Bu ülkelerde hanehalkı tasarruflarının yasal olarak yasaklanması', 'Faiz oranlarının yasa gereği sıfırda tutulması'], 'Yatırım, gelecekte getiri elde etme beklentisine dayanır. Bu getiriye el konulabileceği düşünülürse sermaye birikimi ve yenilik geriler.'),
  ('BM Kalkınma Programı\'nın İnsani Gelişme Endeksi hangi üç boyutu bir araya getirir?', 'Sağlık, eğitim ve yaşam standardı', ['Askerî güç, nüfus ve yüzölçümü', 'İhracat, enflasyon ve faiz', 'Demokrasi, basın özgürlüğü ve yargı bağımsızlığı'], 'Endeks doğuşta beklenen yaşam süresini, eğitim sürelerini ve kişi başı milli geliri (SAGP ile) birleştirir.'),
  ('İktisadi büyüme ile iktisadi kalkınma arasındaki farkı en iyi anlatan ifade hangisidir?', 'Kalkınma, gelir artışının yanında yapısal ve toplumsal dönüşümü de kapsar', ['Büyüme yalnızca kişi başı gelirin düşmesidir', 'Kalkınma yalnızca nüfus artışını ifade eder', 'İkisi tamamen aynı kavramdır ve her zaman aynı ölçütle, aynı birimle ölçülür'], 'Büyüme üretimdeki nicel artıştır. Kalkınma ise eğitim, sağlık, sanayileşme ve kurumsal yapı gibi niteliksel iyileşmeleri de içerir.'),
  ('Bir ülkede en zengin yüzde 20\'lik grubun toplam gelirden aldığı pay yüzde 48, en yoksul yüzde 20\'lik grubun payı yüzde 6\'dır. S80/S20 oranı kaçtır?', '8', ['42', '54', '0,125'], 'S80/S20 oranı en zengin beşte birin gelir payının en yoksul beşte birin payına bölünmesiyle bulunur: 48 / 6 = 8.'),
  ('Bir ülkede en zengin yüzde 10\'un toplam gelirden payı yüzde 30, en yoksul yüzde 40\'ın payı yüzde 15\'tir. Palma oranı kaçtır?', '2', ['0,5', '45', '15'], 'Palma oranı = en zengin yüzde 10\'un payı / en yoksul yüzde 40\'ın payı = 30 / 15 = 2.'),
  ('Gelir dağılımı istatistiklerinde nüfusun gelire göre sıralanıp her biri yüzde 20 olan beş eşit gruba ayrılmasıyla oluşan dilimlere ne ad verilir?', 'Beşte birlik gruplar', ['Ondalık gruplar', 'Çeyreklik gruplar', 'Yüzdelik dilimler ve binde birlik gruplar halinde'], 'Beş eşit dilim, en yoksul yüzde 20\'den en zengin yüzde 20\'ye kadar her grubun toplam gelirden aldığı payı karşılaştırmayı sağlar. Ondalık gruplar ise nüfusu on parçaya böler.'),
  ('Türkiye ekonomisi 2008 küresel finans krizinin etkisiyle hangi yıl yıllık bazda daralmıştır?', '2009', ['2005', '2011', '2013'], 'Dış talebin çökmesi ve sermaye akımlarının durmasıyla Türkiye ekonomisi 2009\'da yaklaşık yüzde 5 küçülmüş, 2010-2011\'de ise hızla toparlanmıştır.'),
  ('Bir ekonomide gerçekleşen reel GSYH 980, potansiyel reel GSYH 1.000 milyar liradır. Üretim açığı potansiyelin yüzde kaçıdır?', '−2', ['2', '−20', '−0,2'], 'Üretim açığı = (gerçekleşen − potansiyel) / potansiyel × 100 = (980 − 1.000) / 1.000 × 100 = −2. Negatif değer ekonominin kapasitesinin altında çalıştığını gösterir.'),
  ('İmalat sanayi için hesaplanan Satın Alma Yöneticileri Endeksi\'nde (PMI) 50 değeri neyi ifade eder?', 'Sektörde bir önceki aya göre değişim olmadığını gösteren eşik', ['Sektörün yüzde 50 küçüldüğünü', 'Kapasitenin yarısının kullanıldığını', 'Enflasyonun yüzde 50 olduğunu ve fiyatların hızla yükseldiğini'], 'PMI anket temelli bir yayılma endeksidir. 50\'nin üzeri genişlemeye, altı daralmaya işaret eder.'),
  ('Türkiye\'de TÜİK ile TCMB işbirliğiyle hesaplanan tüketici güven endeksi 0-200 arasında değer alır. Endeksin 100\'ün altında olması neyi gösterir?', 'Tüketicilerin genel durumu kötümser değerlendirdiğini', ['Tüketicilerin çok iyimser olduğunu', 'Tüketim harcamalarının yüzde 100 arttığını', 'Enflasyonun sıfır olduğunu ve fiyatların sabit kaldığını'], 'Endeks 100\'ün üzerindeyken iyimserlik, altındayken kötümserlik ağır basar. Tüketici güveni, gelecekteki harcama eğilimlerine dair ipucu verir.'),
  ('Ekonomik aktiviteyi aylık olarak izleyen ve GSYH\'nin sanayi bileşeni hakkında erken bilgi veren, TÜİK\'in yayımladığı göstergeye ne ad verilir?', 'Sanayi üretim endeksi', ['Tüketici fiyat endeksi', 'Dış ticaret haddi endeksi', 'Konut fiyat endeksi ve kira endeksi'], 'Sanayi üretim endeksi madencilik, imalat ve enerji sektörlerindeki üretim hacmindeki değişmeyi aylık olarak ölçer.'),
  ('Türkiye\'de resmî GSYH istatistiklerini hesaplayıp yayımlamakla görevli kurum hangisidir?', 'Türkiye İstatistik Kurumu', ['Türkiye Cumhuriyet Merkez Bankası', 'Sermaye Piyasası Kurulu', 'Bankacılık Düzenleme ve Denetleme Kurumu'], 'TÜİK, GSYH\'yi üretim, harcama ve gelir yöntemleriyle çeyreklik ve yıllık olarak hesaplayıp yayımlar.'),
  ('Yabancı turistlerin Antalya\'daki otellerde konaklamak için yaptığı harcamalar, Türkiye\'nin GSYH\'si harcama yöntemiyle hesaplanırken hangi kalemde yer alır?', 'İhracat', ['Hanehalkı tüketimi', 'Kamu harcaması', 'İthalat ve stok değişimi'], 'Yurt içinde üretilip yabancılara satılan hizmetler ihracattır. Turistlerin konaklama harcaması bu nedenle hizmet ihracatı olarak GSYH\'ye girer.'),
  ('Devletin ordu için yurt içindeki bir fabrikadan yeni askerî araçlar satın alması harcama yöntemiyle hangi kalemde yer alır?', 'Kamu harcaması', ['Hanehalkı tüketimi', 'Net ihracat', 'Transfer ödemesi'], 'Devletin mal ve hizmet alımları, savunma harcamaları da dâhil olmak üzere, kamu harcaması (G) kalemine girer.'),
  ('Bir öğrencinin sinemaya gidip bilet alması harcama yöntemiyle GSYH hesaplanırken hangi gruba girer?', 'Hizmet tüketimi', ['Dayanıklı mal tüketimi', 'Sabit sermaye yatırımı', 'Kamu harcaması ve transfer'], 'Sinema gösterimi bir hizmettir ve hanehalkı tarafından satın alındığı için tüketim harcamasının hizmetler alt grubunda yer alır.'),
  ('Ulusal hesaplarda \'cari fiyatlarla GSYH\' ifadesi hangi büyüklüğü anlatır?', 'Nominal GSYH', ['Reel GSYH', 'Kişi başı GSYH', 'Potansiyel GSYH ve üretim açığı'], 'Cari fiyatlar, üretimin yapıldığı yılın fiyatlarıdır. Bu fiyatlarla değerlenen GSYH nominal GSYH\'dir; reel GSYH ise sabit (baz) fiyatlarla ya da zincirlenmiş hacimle hesaplanır.'),
  ('Aşağıdakilerden hangisi makroekonominin temel sorularından biri değildir?', 'Bir pastanenin bir pastaya hangi fiyatı koyması gerektiği', ['Ülkede işsizlik neden yükselir', 'Ekonomi uzun dönemde neden büyür', 'Genel fiyat düzeyi neden artar'], 'Tek bir firmanın fiyat kararı mikroekonominin konusudur. Makroekonomi işsizlik, büyüme ve enflasyon gibi ekonominin bütününe ait toplam büyüklükleri inceler.'),
  ('Makroekonomik başarıyı değerlendirmek için en sık izlenen üç temel gösterge hangileridir?', 'Reel GSYH büyümesi, işsizlik oranı ve enflasyon oranı', ['Borsa endeksi, altın fiyatı ve kira artışı', 'Nüfus, yüzölçümü ve iklim', 'Şirket sayısı, banka şubesi sayısı ve otomobil sayısı'], 'Bir ekonominin ne kadar ürettiği, kaynaklarını ne ölçüde kullandığı ve fiyat istikrarı bu üç göstergeyle özetlenir.'),
  ('Bir ülkenin büyüme oranının bir yıl eksi yüzde 2 olarak açıklanması ne anlama gelir?', 'Reel üretim bir önceki yıla göre yüzde 2 azalmıştır', ['Ekonomi yüzde 2 hızla büyümüştür', 'Fiyatlar yüzde 2 düşmüştür', 'İşsizlik oranı yüzde 2\'ye inmiştir ve istihdam artmıştır'], 'Büyüme oranı reel GSYH\'deki yüzde değişimdir; negatif değer ekonominin küçüldüğünü, yani daraldığını gösterir.'),
  ('Uzun dönemde bir ekonominin üretim kapasitesini belirleyen temel kaynaklar hangileridir?', 'İşgücü, sermaye birikimi ve teknoloji', ['Para arzı, faiz ve döviz kuru', 'Vergi oranları, gümrük tarifeleri ve kotalar', 'Borsa endeksi, tahvil faizi ve altın fiyatı'], 'Kısa dönemde talep önemli olsa da uzun dönemde ne kadar üretilebileceğini emek, sermaye ve bunların ne kadar verimli kullanıldığını belirleyen teknoloji belirler.'),
  ('TÜİK\'in GSYH verileri genellikle hangi sıklıkla açıklanır?', 'Çeyreklik', ['Günlük', 'Haftalık', 'On yılda bir yapılan sayımlarla'], 'GSYH, çeyrek dönemler itibarıyla hesaplanır; yıllık GSYH dört çeyreğin toplamıyla elde edilir.'),
  ('Bir ülkede nüfus azalırken GSYH sabit kalırsa kişi başı GSYH nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Sıfıra iner'], 'Kişi başı GSYH, GSYH\'nin nüfusa bölünmesidir. Pay sabitken payda küçülürse oran büyür.'),
  ('Bir fabrikadan işten çıkarılan ve ertesi günden itibaren aktif olarak iş aramaya başlayan bir işçi işgücü istatistiklerinde nasıl sınıflanır?', 'İşsiz', ['İşgücü dışında', 'İstihdamda', 'Eksik istihdamda'], 'Kişi çalışmamakta, iş aramakta ve işe başlamaya hazır bulunmaktadır; bu üç koşul onu işsiz kategorisine yerleştirir.'),
  ('Son yıllarda gençlerin işgücüne katılma oranının pek çok ülkede düşmesinin en olağan nedenlerinden biri hangisidir?', 'Eğitimde geçirilen sürenin uzaması', ['Gençlerin istatistiklerden çıkarılması', 'Asgari yaşın 30\'a yükseltilmesi', 'Gençlerin tamamının emekli olması ve aylık alması'], 'Üniversiteye ve lisansüstü eğitime devam edenlerin oranı arttıkça çalışmayan ve iş aramayan gençlerin payı da yükselir; bu, işgücüne katılımı düşürür.'),
  ('İşsizlik sigortası kapsamında ödenen işsizlik ödeneğinin temel amacı hangisidir?', 'İşini kaybeden çalışanın gelir kaybını geçici olarak kısmen karşılamak', ['İşverenlerin kârlarını artırmak', 'Çalışanların ücretlerini kalıcı olarak ikiye katlamak', 'İşsizlerin iş aramasını yasaklamak ve evde kalmalarını sağlamak'], 'Ödenek, iş arama süresince tüketimin sürdürülmesine yardım eder; aynı zamanda durgunluklarda toplam talebi destekler.'),
  ('Bir ekonomide işsizliğin büyük bölümü resesyon nedeniyle talebin çökmesinden kaynaklanıyorsa, bu işsizliği azaltmak için öncelikle neye ihtiyaç vardır?', 'Toplam talebin yeniden canlanmasına', ['İşçilerin yeni meslekler öğrenmesine', 'Mevsim koşullarının değişmesine', 'İş arama sitelerinin kapatılmasına ve bilgi akışının kısıtlanmasına'], 'Konjonktürel işsizliğin kaynağı talep yetersizliğidir; bu yüzden harcamaların toparlanmasıyla birlikte azalır.'),
  ('Kullanılabilir geliri 500 bin lira olan bir hane 450 bin lirasını harcamaktadır. Bu hanenin tasarruf oranı yüzde kaçtır?', '10', ['90', '50', '11,1'], 'Tasarruf 500 − 450 = 50 bin liradır. Tasarruf oranı 50 / 500 = 0,10, yani yüzde 10\'dur.'),
  ('Konut kredisi faizlerinin belirgin biçimde düşmesi, diğer koşullar aynıyken konut yatırımlarını nasıl etkiler?', 'Artırır', ['Azaltır', 'Etkilemez', 'Tamamen durdurur'], 'Konutlar genellikle uzun vadeli krediyle alınır. Faizin düşmesi aylık ödemeleri azaltarak konut talebini ve yeni inşaatları artırır.'),
  ('Ulusal hesaplarda ayrılan amortisman, sermaye stokundaki hangi kaybın karşılığıdır?', 'Kullanım ve eskime nedeniyle makine ile binaların değer yitirmesi', ['Hisse senedi fiyatlarının düşmesi', 'Bankalardaki mevduatın azalması', 'Enflasyon nedeniyle paranın değer kaybetmesi ve kurun yükselmesi'], 'Sermaye malları kullanıldıkça aşınır ve teknolojik olarak eskir. Bu değer kaybı, üretimin bir maliyeti olarak amortisman adıyla ayrılır.'),
  ('Bir ekonominin potansiyelinin çok üzerinde büyüyüp enflasyonun hızlandığı, işgücü ve kapasite darboğazlarının ortaya çıktığı duruma ne ad verilir?', 'Aşırı ısınma', ['Durgunluk', 'Deflasyon', 'Likidite tuzağı ve faiz tabanı'], 'Aşırı ısınmada talep üretim kapasitesini zorlar; ücretler ve fiyatlar hızla yükselir ve bu durum genellikle sürdürülemez.'),
  ('Resesyon dönemlerinde şirket kârları ile iflas eden firma sayısı genellikle nasıl değişir?', 'Kârlar azalır, iflaslar artar', ['Kârlar artar, iflaslar azalır', 'İkisi de artar', 'İkisi de değişmez, yalnızca fiyatlar değişir'], 'Satışların düşmesi kârları aşındırır; borcunu ödeyemeyen firmaların sayısı artar. İflas sayısı bu yüzden konjonktür karşıtı bir göstergedir.'),
  ('Enflasyonu düşürmeye çalışan bir ekonominin bunu resesyona girmeden, yalnızca büyümeyi ılımlı biçimde yavaşlatarak başarmasına ne ad verilir?', 'Yumuşak iniş', ['Sert iniş', 'Çift dip', 'Aşırı ısınma ve canlanma'], 'Yumuşak iniş, enflasyonu düşürürken üretim ve istihdamda büyük kayıp yaşanmamasıdır. Bu süreç sert bir daralmayla sonuçlanırsa sert iniş denir.'),
  ('Bir ülkede yağışların çok az olduğu bir yıl tarımsal üretimin ülke genelinde sert düşmesi toplam talep-toplam arz modelinde hangi tür şoktur?', 'Olumsuz arz şoku', ['Olumlu talep şoku', 'Olumsuz talep şoku', 'Olumlu arz şoku'], 'Üretim koşullarının bozulması maliyetleri artırır ve kısa dönem toplam arz eğrisini sola kaydırır; fiyatlar yükselirken üretim düşer.'),
  ('Hükümetin büyük çaplı bir altyapı programıyla mal ve hizmet alımlarını artırması toplam talep eğrisini kısa dönemde nasıl etkiler?', 'Sağa kaydırır', ['Sola kaydırır', 'Etkilemez', 'Dikey hâle getirir'], 'Kamu harcaması toplam talebin bileşenlerinden biridir; artması her fiyat düzeyinde talep edilen toplam üretimi artırır.'),
  ('Bir ülkeye çalışma çağında çok sayıda göçmenin gelip işgücüne katılması uzun dönem toplam arz eğrisini nasıl etkiler?', 'Sağa kaydırır', ['Sola kaydırır', 'Etkilemez', 'Yatay hâle getirir'], 'İşgücünün artması ekonominin potansiyel üretimini büyütür; bu, uzun dönem toplam arzın sağa kayması demektir.'),
  ('Bir ekonominin bir durgunluktan çıkıp üretimin yeniden artmaya başladığı ilk döneme ne ad verilir?', 'Canlanma', ['Tepe', 'Kriz', 'Stagflasyon'], 'Dip noktasının ardından üretim ve istihdamın artmaya başladığı evre canlanma ya da toparlanma olarak adlandırılır.'),
  ('Toplam talep eğrisinin bileşenleri olan harcama kalemleri hangileridir?', 'Tüketim, yatırım, kamu harcaması ve net ihracat', ['Ücret, rant, faiz ve kâr', 'Tasarruf, vergi ve ithalat', 'Emek, sermaye, doğal kaynak ve girişimci'], 'Toplam talep, ekonomideki toplam harcamadır: C + I + G + NX. Ücret ve kâr gelir yönteminin, tasarruf ve vergi ise sızıntıların kalemleridir.'),
  ('Bir ülkenin fabrikalarına her yıl daha fazla makine ve teçhizat eklemesi, büyümenin hangi kaynağına örnektir?', 'Fiziki sermaye birikimi', ['Nüfus artışı', 'Doğal kaynak keşfi', 'Beşeri sermaye birikimi'], 'Makine, bina ve teçhizat gibi insan yapımı üretim araçlarının artması fiziki sermaye birikimidir ve işçi başına üretimi yükseltir.'),
  ('Bir şirketin aynı işçi ve makinelerle, yalnızca üretim hattını yeniden düzenleyip yönetim yöntemlerini iyileştirerek daha fazla üretmesi büyüme muhasebesinde hangi kalemde görünür?', 'Toplam faktör verimliliği artışı', ['Sermaye birikimi', 'İşgücü artışı', 'Stok yatırımı'], 'Girdiler değişmeden üretimin artması, sermaye ve emekle açıklanamayan kısma, yani toplam faktör verimliliğine yansır.'),
  ('Ülkeler arasında karşılaştırıldığında, yatırımların GSYH\'ye oranı ile uzun dönem büyüme hızı arasında genellikle nasıl bir ilişki gözlenir?', 'Pozitif bir ilişki', ['Negatif bir ilişki', 'Hiçbir ilişki yoktur', 'Yalnızca petrol ülkelerinde ilişki vardır, diğerlerinde yoktur'], 'Yatırıma daha büyük pay ayıran ülkeler sermaye birikimini hızlandırdığından, ortalamada daha hızlı büyüme eğilimindedir; ancak yatırımın verimliliği de önemlidir.'),
  ('Bir ülkede sıtma gibi salgın hastalıkların azaltılması ve beslenmenin iyileşmesi ekonomik büyümeye hangi yoldan katkı sağlar?', 'Çalışanların daha sağlıklı ve verimli olmasıyla', ['Nüfusun hızla azalmasıyla', 'Vergilerin otomatik olarak düşmesiyle', 'İthalatın yasaklanmasıyla ve dış ticaretin kesilmesiyle'], 'Sağlık, beşeri sermayenin bir parçasıdır. Hastalık nedeniyle iş günü kaybının azalması ve çocukların daha iyi gelişmesi verimliliği yükseltir.'),
  ('Nitelikli doktor ve mühendislerin daha yüksek ücretler için yurt dışına göç etmesi, kaynak ülkenin uzun dönem büyüme potansiyelini en çok hangi yoldan etkiler?', 'Beşeri sermaye kaybıyla', ['Fiziki sermaye stokunu artırarak', 'Doğal kaynakları çoğaltarak', 'Teknolojik ilerlemeyi kendiliğinden hızlandırarak ve verimliliği artırarak'], 'Beyin göçü, ülkenin eğitime yaptığı yatırımın getirisini başka ülkelere aktarır ve yerel üretimde kullanılabilecek nitelikli emeği azaltır.'),
  ('Yetişkin okuryazarlık oranı bir ülkenin kalkınma düzeyi hakkında doğrudan hangi alanda bilgi verir?', 'Eğitim ve beşeri sermaye', ['Dış ticaret dengesi', 'Kamu borcu', 'Döviz rezervleri ve kur politikası'], 'Okuryazarlık, temel eğitime erişimin ve işgücünün niteliğinin basit bir göstergesidir; bu yüzden kalkınma ölçütlerinde sıkça kullanılır.'),
  ('Kişi başı geliri aynı olan iki ülkeden birinde ortalama yaşam süresi 80, diğerinde 60 yıldır. Bu fark bize hangi sonucu düşündürür?', 'Kişi başı gelirin tek başına kalkınma düzeyini tam yansıtmadığını', ['İki ülkenin kalkınma düzeyinin kesinlikle aynı olduğunu', 'Yaşam süresinin ekonomiyle hiçbir ilgisi olmadığını', 'Kişi başı gelirin yanlış hesaplandığını ve düzeltilmesi gerektiğini'], 'Gelir aynı olsa da sağlık hizmetleri ve gelir dağılımı gibi etkenler farklı olabilir. Bu nedenle kalkınma çok boyutlu göstergelerle değerlendirilir.'),
  ('Ekonomik büyüme ile ilgili olarak \'teknolojik ilerleme\' kavramı en iyi nasıl tanımlanır?', 'Aynı girdilerle daha fazla ya da daha iyi ürün üretebilme bilgisindeki artış', ['Fabrika sayısının artması', 'Ülkenin yüzölçümünün genişlemesi', 'Çalışılan saat sayısının artması ve resmî tatillerin azaltılması'], 'Teknoloji, girdilerin üretime nasıl dönüştürüleceğine ilişkin bilgidir. Bu bilgi geliştikçe aynı emek ve sermayeyle daha fazla üretim yapılır.'),
  ('Türkiye\'de GSYH içinde en büyük payı hangi geniş sektör grubu alır?', 'Hizmetler', ['Tarım', 'Madencilik', 'Enerji üretimi'], 'Ticaret, ulaştırma, finans, eğitim, sağlık ve kamu hizmetlerini kapsayan hizmetler sektörü Türkiye\'de katma değerin yarısından fazlasını oluşturur.'),
  ('Kadınların işgücüne katılım oranının artması, bir ekonominin potansiyel üretimini nasıl etkiler?', 'Artırır, çünkü işgücü genişler', ['Azaltır, çünkü işsizlik kesin artar', 'Etkilemez, potansiyel yalnızca teknolojiye bağlıdır', 'Yalnızca fiyatları düşürür ve üretimi değiştirmez'], 'Çalışan ve iş arayan kişi sayısının artması kullanılabilir emek miktarını büyütür; bu da uzun dönem üretim kapasitesini yükseltir.'),
  ('Yasal emeklilik yaşının yükseltilmesi, kısa dönemdeki diğer etkileri bir yana, işgücü arzını nasıl etkiler?', 'Artırır', ['Azaltır', 'Değiştirmez', 'Önce sıfıra indirir'], 'İnsanlar daha uzun süre çalışma hayatında kaldıkça işgücündeki kişi sayısı artar; bu da yaşlanan toplumlarda potansiyel büyümeyi destekler.'),
  ('Tam zamanlı çalıştığı hâlde hanesinin geliri yoksulluk sınırının altında kalan kişileri tanımlamak için kullanılan kavram hangisidir?', 'Çalışan yoksullar', ['Gizli işsizler', 'Cesareti kırılmış işçiler', 'Potansiyel işgücü ve NEET'], 'Çalışan yoksulluk, istihdamın tek başına yoksulluktan kurtulmayı garanti etmediğini; düşük ücret ve kalabalık hane gibi etkenlerin de önemli olduğunu gösterir.'),
  ('Devletin bir okulda çalışan öğretmene ödediği maaş ile bir emekliye ödediği aylık, GSYH hesabında nasıl ayrışır?', 'Öğretmen maaşı kamu harcamasına girer, emekli aylığı girmez', ['İkisi de kamu harcamasına girer', 'Emekli aylığı kamu harcamasına girer, öğretmen maaşı girmez', 'İkisi de hanehalkı tüketimi olarak sayılır ve aynı kalemdedir'], 'Öğretmen maaşı, devletin o dönemde satın aldığı eğitim hizmetinin karşılığıdır. Emekli aylığı ise cari bir hizmet karşılığı olmayan transferdir.'),
  ('Bir ülkede faktör maliyetiyle milli gelir 900 milyar lira, toplam ücret ödemeleri 540 milyar liradır. Emeğin milli gelirdeki payı yüzde kaçtır?', '60', ['54', '40', '90'], 'Emek payı = ücretler / milli gelir = 540 / 900 = 0,60, yani yüzde 60\'tır.'),
  ('Ortalama tüketim eğilimi 0,85 olan bir hanenin ortalama tasarruf eğilimi kaçtır?', '0,15', ['0,85', '1,85', '0,5'], 'Gelir tüketim ve tasarrufa ayrıldığından ortalama tüketim ve tasarruf eğilimlerinin toplamı 1\'dir: 1 − 0,85 = 0,15.'),
  ('İşgücünün 30 milyon kişide sabit kaldığı bir ülkede işsizlik oranı yüzde 10\'dan yüzde 8\'e inmiştir. İstihdam kaç kişi artmıştır?', '600 bin', ['2 milyon', '60 bin', '2,4 milyon'], 'İstihdam önce 30 × 0,90 = 27 milyon, sonra 30 × 0,92 = 27,6 milyondur. Artış 0,6 milyon, yani 600 bin kişidir.'),
  ('İnsani Gelişme Endeksi\'nde bir ülkenin alabileceği en yüksek değer kaçtır?', '1', ['10', '100', '1.000'], 'Endeks 0 ile 1 arasında değer alır; değer 1\'e yaklaştıkça insani gelişme düzeyi yükselir.'),
  ('İnsani Gelişme Raporu\'nda ülkeler endeks değerlerine göre kaç insani gelişme grubuna ayrılır?', 'Dört', ['İki', 'Üç', 'Altı'], 'Ülkeler çok yüksek, yüksek, orta ve düşük insani gelişme olmak üzere dört gruba ayrılır.'),
  ('Sanayi Devrimi\'nden önceki binlerce yıl boyunca dünyada kişi başı gelirin seyri için hangisi doğrudur?', 'Çok yavaş arttığı ve büyük ölçüde durgun kaldığı', ['Her yıl ortalama yüzde 3 arttığı', 'Her yüzyılda ikiye katlandığı', 'Sürekli ve hızla düştüğü ve her yüzyılda yarıya indiği'], 'Uzun dönem tahminleri, 18. yüzyıl sonuna kadar kişi başı gelirin neredeyse yerinde saydığını; sürekli ve hızlı artışın Sanayi Devrimi\'yle başladığını gösterir.'),
  ('Ülkelerin ekonomik büyüklüğünü ya da pazar hacmini karşılaştırmak isteyen bir analist, yaşam standardı yerine bu amaçla hangi göstergeyi kullanmalıdır?', 'Toplam GSYH', ['Kişi başı GSYH', 'Gini katsayısı', 'İşgücüne katılma oranı ve istihdam oranı'], 'Toplam GSYH bir ekonominin bütün olarak ne kadar ürettiğini, dolayısıyla büyüklüğünü gösterir. Yaşam standardını karşılaştırmak için ise kişi başı değerler kullanılır.'),
  ('Bir ekonominin sermaye stoku 3.000 milyar lira, yıllık GSYH\'si 1.000 milyar liradır. Ortalama sermaye-hasıla oranı kaçtır?', '3', ['0,33', '4.000', '2.000'], 'Sermaye-hasıla oranı K / Y = 3.000 / 1.000 = 3\'tür; yani bir birim üretim için ortalama üç birim sermaye kullanılmaktadır.'),
  ('Bir ülkede büyük bir doğal gaz yatağının keşfedilmesi, büyümenin hangi kaynağında artış anlamına gelir?', 'Doğal kaynaklar', ['Beşeri sermaye', 'Toplam faktör verimliliği', 'İşgücü'], 'Yer altı ve yer üstü kaynaklar üretimde kullanılabilecek girdilerdir; yeni bir yatak bulunması bu kaynak stokunu artırır.'),
  ('Makroekonomide yatırım ile sermaye stoku arasındaki ilişki en doğru nasıl ifade edilir?', 'Yatırım, sermaye stokunu artıran bir akımdır', ['Yatırım ile sermaye stoku aynı şeydir', 'Sermaye stoku, yatırımın yıllık değişimidir', 'Yatırım arttıkça sermaye stoku her zaman azalır ve aşınır'], 'Sermaye stoku belirli bir andaki birikimdir. Gayrisafi yatırım bu stoka eklenir, amortisman ise stoktan düşer.'),
  ('Diğer harcama kalemleri değişmezken bir ülkenin ihracatının artması o ülkenin GSYH\'sini nasıl etkiler?', 'Artırır', ['Azaltır', 'Etkilemez', 'Yalnızca yabancı ülkelerin GSYH\'sini artırır'], 'İhracat yurt içinde üretilip yabancılara satılan mallardır; artması yurt içi üretimin, dolayısıyla GSYH\'nin artması demektir.'),
  ('Türkiye\'de TÜİK işgücü istatistiklerini (işsizlik oranı gibi) hangi sıklıkla yayımlar?', 'Aylık', ['On yılda bir', 'Beş yılda bir', 'Yalnızca nüfus sayımı yıllarında'], 'TÜİK Hanehalkı İşgücü Araştırması sonuçlarını aylık olarak yayımlar; ayrıca çeyreklik ve yıllık sonuçlar da açıklanır.'),
  ('Ekonomik verilerde \'öncü\', \'eşzamanlı\' ve \'gecikmeli\' gösterge ayrımı neye göre yapılır?', 'Göstergenin konjonktürdeki dönüm noktalarına göre ne zaman hareket ettiğine', ['Göstergenin hangi ülkede derlendiğine', 'Göstergenin hangi para birimiyle ve hangi kurum tarafından ölçülüp yayımlandığına', 'Göstergenin sayısal değerinin büyüklüğüne ve basamak sayısına'], 'Öncü göstergeler dönüm noktalarından önce, eşzamanlılar aynı anda, gecikmeliler ise sonra değişir.'),
  ('Gelir düzeyi yükseldikçe ülkelerin yatırım harcamalarının yanı sıra hangi tür tüketimin payının genellikle arttığı gözlenir?', 'Hizmet tüketiminin', ['Temel gıda tüketiminin', 'Yakacak odun tüketiminin', 'Tarımsal ham madde tüketiminin'], 'Gelir arttıkça haneler eğitim, sağlık, eğlence ve seyahat gibi hizmetlere daha büyük pay ayırır; bu da ekonominin hizmetler ağırlıklı yapıya geçmesini destekler.'),
  ('Bir ülkede firmaların gelecekteki satış beklentilerinin kötüleşmesi, faizler değişmese bile yatırım harcamalarını nasıl etkiler?', 'Azaltır', ['Artırır', 'Etkilemez', 'Önce sıfıra indirir, sonra iki katına çıkarır'], 'Yatırımın getirisi beklenen satışlara bağlıdır. Satış beklentisi düşünce kârlı görünen proje sayısı azalır.'),
  ('Nüfusu 80 milyon olan bir ülkede 12 milyon kişi yoksulluk sınırının altında yaşamaktadır. Yoksulluk oranı yüzde kaçtır?', '15', ['12', '6,7', '20'], 'Yoksulluk oranı = yoksul sayısı / toplam nüfus = 12 / 80 = 0,15, yani yüzde 15\'tir.'),
  ('Uzun dönemde gelir eşitsizliğini azaltmaya en çok katkı sağlaması beklenen etkenlerden biri hangisidir?', 'Nitelikli eğitime erişimin yaygınlaştırılması', ['Eğitim süresinin kısaltılması', 'Okul sayısının azaltılması', 'Yalnızca yüksek gelirlilere burs verilmesi ve bunun yaygınlaştırılması'], 'Eğitim, beşeri sermayeyi ve kazanç olanaklarını artırır. Erişimin geniş kesimlere yayılması gelir farklarını kuşaklar boyunca daraltabilir.'),
  ('Tüketici kredisine erişimin kolaylaşması ve kredi kartı kullanımının yaygınlaşması, kısa dönemde toplam tüketimi nasıl etkiler?', 'Artırır, çünkü haneler gelecekteki gelirlerini bugün harcayabilir', ['Azaltır, çünkü borçlanma yasaklanır', 'Etkilemez, çünkü tüketim yalnızca fiyatlara bağlıdır', 'Önce sıfıra indirir, sonra iki katına çıkarır ve en sonunda eski düzeyine döner'], 'Kredi olanağı, likidite kısıtı olan hanelerin tüketimi öne çekmesine izin verir. Ancak borçların geri ödenmesi ileride tüketimi kısabilir.'),
  ('Bir ülkenin büyümesi için \'yeterli tasarrufun yatırıma dönüşmesi\' en çok hangi kurumların sağlıklı işlemesine bağlıdır?', 'Bankalar ve sermaye piyasaları gibi finansal aracılar', ['Yalnızca vergi daireleri', 'Yalnızca nüfus müdürlükleri', 'Spor kulüpleri ve kültür merkezleri ile belediyelerin sosyal tesisleri'], 'Finansal sistem hanehalklarının tasarruflarını toplayıp üretken yatırımlara aktarır. Bu aracılık zayıfsa tasarruflar atıl kalabilir ya da verimsiz kullanılabilir.'),
  ('Bir bankanın müşterilerinden aldığı hesap işletim ve havale ücretleri GSYH açısından nasıl değerlendirilir?', 'Finansal hizmet üretiminin karşılığı olarak GSYH\'ye girer', ['Transfer olduğu için GSYH\'ye girmez', 'Vergi sayılır ve GSYH\'den düşülür', 'Yalnızca ithalat olarak kaydedilir ve GSYH\'den düşülür'], 'Bankalar ödeme, saklama ve aracılık hizmeti üretir. Bu hizmetler için alınan ücretler hizmet sektörünün katma değerine yansır.'),
  ('Bir otomobil şirketinin yeni bir üretim fabrikası kurması harcama yöntemiyle GSYH hesaplanırken hangi kalemde yer alır?', 'Yatırım', ['Tüketim', 'Kamu harcaması', 'Net ihracat'], 'Firmaların üretimde uzun süre kullanacakları bina ve makinelere yaptığı harcamalar sabit sermaye yatırımıdır.'),
  ('Bir hanehalkının ödediği aylık elektrik ve su faturaları harcama yöntemiyle hangi kalemde yer alır?', 'Tüketim', ['Yatırım', 'Kamu harcaması', 'Stok değişimi'], 'Hanehalklarının günlük yaşamları için satın aldığı mal ve hizmetler, faturalar da dâhil, tüketim harcamasıdır.'),
  ('İki ülkenin yaşam standartlarını karşılaştırmak için aşağıdaki göstergelerden hangisi en uygundur?', 'Kişi başı reel GSYH', ['Toplam nominal GSYH', 'Toplam ihracat', 'Nominal para arzı'], 'Toplam büyüklükler nüfus farkını, nominal büyüklükler de fiyat farkını yansıtmaz. Kişi başı reel GSYH her iki etkiyi de dikkate alır.'),
  ('Ekonomik büyümenin topluma sağladığı en doğrudan yararlardan biri hangisidir?', 'Yeni iş olanakları ve artan gelirler', ['Bütün fiyatların kesin olarak düşmesi', 'Vergilerin tamamen kaldırılması', 'Nüfusun azalması ve kentlerin boşalması'], 'Üretimin artması firmaların daha fazla çalışan istihdam etmesini ve hanelerin gelirlerinin yükselmesini sağlar.'),
  ('Hızlı ekonomik büyümenin dikkat edilmezse yol açabileceği olumsuz yan etkilerden biri hangisidir?', 'Çevre kirliliği ve doğal kaynakların tükenmesi', ['İşsizliğin kesin olarak artması', 'Kişi başı gelirin kesin olarak düşmesi', 'Bütün sektörlerde üretimin azalması ve ekonominin küçülmesi'], 'Üretimin artması enerji ve kaynak kullanımını artırır; çevresel maliyetler GSYH\'de görünmediği için bu etkiler ayrıca izlenmelidir.'),
  ('Bir ülkede ekonomik genişleme döneminde genellikle hangi gelişme gözlenir?', 'İstihdam ve üretim artar', ['İflas sayısı hızla artar', 'Fabrikalarda kapasite kullanımı düşer', 'İşsizlik oranı sürekli yükselir'], 'Genişleme evresinde talep artar, firmalar üretimi ve işe alımları artırır; bu yüzden üretim ve istihdam birlikte yükselir.'),
  ('Makroekonomide \'genel fiyat düzeyi\' ifadesiyle ne kastedilir?', 'Ekonomideki mal ve hizmet fiyatlarının ortalama düzeyi', ['En pahalı malın fiyatı', 'Altının gram fiyatı', 'Bir ülkenin döviz kuru ve faiz oranı'], 'Genel fiyat düzeyi, tek tek malların değil, ekonomideki bütün fiyatların ağırlıklı ortalamasını ifade eder ve TÜFE ya da deflatör gibi endekslerle ölçülür.'),
  ('Bir ülkenin üretiminin bir yıldan diğerine artıp artmadığını anlamak için nominal GSYH yerine reel GSYH\'nin kullanılmasının nedeni nedir?', 'Nominal GSYH fiyat artışları nedeniyle üretim değişmese bile artabilir', ['Reel GSYH her zaman daha büyük bir sayıdır', 'Nominal GSYH hiçbir ülkede hesaplanmaz', 'Reel GSYH yalnızca ihracatı ölçtüğü için daha kolay hesaplanır'], 'Fiyatların yükselmesi nominal değerleri şişirir. Üretimdeki gerçek değişimi görmek için sabit fiyatlarla hesaplanan reel GSYH kullanılır.'),
  ('Aşağıdakilerden hangisi bir ekonominin \'toplam\' (makro) büyüklüğüne örnektir?', 'Ülkedeki toplam istihdam', ['Bir bakkalın günlük satışı', 'Bir öğrencinin aylık harçlığı', 'Bir fabrikanın tek bir makinesinin üretimi'], 'Makroekonomi ekonominin bütününe ait toplam büyüklükleri inceler; tek tek birimlerin kararları mikroekonominin konusudur.'),
  ('Bir ekonomide üretim artarken işsizlik oranının da düşmesi, Okun yasası ile tutarlı mıdır?', 'Evet; üretim artışı genellikle işsizliğin düşmesiyle birlikte görülür', ['Hayır; Okun yasası üretim arttıkça işsizliğin arttığını söyler', 'Hayır; Okun yasası işsizlik ile üretim arasında ilişki olmadığını söyler', 'Evet; ancak yalnızca enflasyon sıfır olduğunda ve faiz sabitken'], 'Okun yasası, üretimin potansiyelin üzerinde arttığı dönemlerde işsizliğin düştüğünü, gerisinde kaldığı dönemlerde ise yükseldiğini anlatır.'),
  ('Bir ülkede işsizlik oranı yükselirken hanehalklarının tüketim harcamaları genellikle nasıl etkilenir?', 'Gelir kayıpları ve belirsizlik nedeniyle azalma eğilimine girer', ['Hızla artar', 'Hiç değişmez', 'Önce iki katına çıkar, sonra sabitlenir ve bir daha değişmez'], 'İşini kaybeden hanelerin geliri düşer, işini koruyanlar da ihtiyat amacıyla daha çok tasarruf edebilir; her iki etki tüketimi azaltır.'),
  ('Gerçek GSYH büyümesini hesaplamak için kullanılan fiyatların belirli bir yılın fiyatları olarak sabit tutulduğu yıla ne ad verilir?', 'Baz yılı', ['Mali yıl', 'Artık yıl', 'Takvim yılı'], 'Reel GSYH, cari yılın üretim miktarlarının seçilen baz yılının fiyatlarıyla çarpılmasıyla bulunur; böylece fiyat değişiminin etkisi ayıklanır.'),
  ('Bir ülkede birkaç ay üst üste otomobil ve beyaz eşya satışlarının belirgin biçimde düştüğü gözleniyor. Bu gelişme ekonominin gidişatı hakkında en çok neye işaret edebilir?', 'Hanehalkı talebinin zayıfladığına ve ekonominin yavaşlayabileceğine', ['Ekonominin aşırı ısındığına', 'Enflasyonun kesinlikle hızlanacağına', 'İşsizliğin kesin olarak sıfıra ineceğine ve istihdamın patlayacağına'], 'Dayanıklı mal alımları kolayca ertelenebildiği için hanelerin gelir ve güven durumundaki bozulmayı erken yansıtır; bu yüzden yavaşlamanın ilk işaretlerinden biri olabilir.'),
  ('Bir ülkenin \'durgunluk\' yaşadığı söylendiğinde genellikle hangi durum kastedilir?', 'Ekonomik faaliyetin genel olarak yavaşlayıp üretimin azalması', ['Fiyatların hızla artması', 'İhracatın rekor kırması', 'Faiz oranlarının yükselmesi ve borsanın tavan yapması'], 'Durgunluk ya da resesyon, üretim, gelir, istihdam ve satışların ekonomi genelinde gerilemesidir.'),
  ('İşgücü piyasasının \'sıkı\' olduğu söylendiğinde genellikle hangi durum kastedilir?', 'İşsizliğin düşük, boş iş ilanlarının çok olduğu ve işverenlerin eleman bulmakta zorlandığı durum', ['İşsizliğin çok yüksek olduğu durum', 'Ücretlerin hızla düştüğü durum', 'Bütün fabrikaların kapandığı ve istihdamın çöktüğü durum'], 'Sıkı bir işgücü piyasasında işçilerin pazarlık gücü artar; bu da ücretler ve dolayısıyla fiyatlar üzerinde yukarı yönlü baskı yaratabilir.'),
  ('Bir kişinin kazandığı piyango ikramiyesi, gelir yöntemiyle GSYH hesaplanırken neden faktör gelirleri arasında yer almaz?', 'Bir üretim faaliyetinin karşılığı olmadığı için', ['Vergiden muaf olduğu için', 'Tutarı çok büyük olduğu için', 'Bankaya yatırıldığı ve tasarruf sayıldığı için'], 'Gelir yöntemi yalnızca üretime katılan faktörlerin kazandığı ücret, rant, faiz ve kârı toplar. Piyango ikramiyesi bir paranın el değiştirmesidir; yeni üretim yaratmaz.'),
  ('Keynesyen yaklaşıma göre hanehalkı tüketim harcamalarının en önemli belirleyicisi hangisidir?', 'Kullanılabilir gelir', ['Hava durumu', 'Döviz rezervleri', 'Nüfus sayımının yapıldığı yıl'], 'Keynesyen tüketim fonksiyonu tüketimi esas olarak vergiler sonrası elde kalan gelire bağlar; servet, faiz ve beklentiler gibi etkenler fonksiyonu kaydırır.'),
  ('Diğer her şey aynıyken hanehalklarından alınan gelir vergilerinin artırılması tüketimi hangi yoldan etkiler?', 'Kullanılabilir geliri azaltarak tüketimi düşürür', ['Kullanılabilir geliri artırarak tüketimi yükseltir', 'Yalnızca ithalatı artırır', 'Hiçbir etkisi olmaz, çünkü vergi tüketimle ilgisizdir'], 'Kullanılabilir gelir, kişisel gelirden doğrudan vergiler düşülerek bulunur. Bu gelir azaldığında tüketim fonksiyonu boyunca tüketim de azalır.'),
  ('Bir ülkede işgücünün yılda yüzde 1, işçi başına verimliliğin yüzde 2 artması bekleniyor. Potansiyel büyüme hızı yaklaşık yüzde kaçtır?', '3', ['2', '1', '0,5'], 'Potansiyel büyüme yaklaşık olarak işgücü artışı ile işçi başına verimlilik artışının toplamıdır: 1 + 2 = yüzde 3.'),
  ('Farklı ülkelerin GSYH verilerinin birbiriyle karşılaştırılabilmesini sağlayan temel etken hangisidir?', 'Ortak uluslararası ulusal hesaplar standartlarının kullanılması', ['Bütün ülkelerin aynı para birimini kullanması', 'Bütün ülkelerin aynı nüfusa sahip olması', 'GSYH\'nin her ülkede aynı gün açıklanması ve aynı kurumca hesaplanması'], 'BM\'nin Ulusal Hesaplar Sistemi gibi standartlar kavramların, tanımların ve yöntemlerin ülkeler arasında uyumlu olmasını sağlar.'),
  ('Kısa dönem toplam arz eğrisi pozitif eğimliyken toplam talebin azalması kısa dönemde hangi sonucu doğurur?', 'Üretim ve fiyat düzeyi birlikte düşer', ['Üretim artar, fiyatlar düşer', 'Üretim düşer, fiyatlar artar', 'Üretim ve fiyat düzeyi birlikte artar'], 'Talep sola kaydığında yeni denge, pozitif eğimli arz eğrisi üzerinde hem daha düşük fiyat hem de daha düşük üretimle oluşur.'),
  ('İşsizlik oranının ölçülmesinde \'işgücü\' paydasının kullanılmasının, toplam nüfusun kullanılmasına göre üstünlüğü hangisidir?', 'Çalışması beklenmeyen çocuk, öğrenci ve emeklileri hesaba katmaması', ['Hesabı daha karmaşık hâle getirmesi', 'Yalnızca kamu çalışanlarını kapsaması', 'Sonucu her zaman daha yüksek göstermesi ve işsizliği abartması'], 'İşsizlik, çalışmak isteyip iş bulamayanların sorunudur. Bu nedenle oran, çalışan ve iş arayanlardan oluşan işgücüne göre hesaplanır.'),
  ('Bir ülkede işgücüne katılma oranının yükselmesi, aynı dönemde yeterli iş yaratılmazsa işsizlik oranını nasıl etkileyebilir?', 'Yükseltebilir', ['Kesinlikle düşürür', 'Hiçbir koşulda etkilemez', 'Sıfıra indirir'], 'İşgücüne yeni katılanlar iş arayan kişilerdir. Bunların hepsi iş bulamazsa işsiz sayısı ve işsizlik oranı artar.'),
  ('Bir ülkede gelir dağılımının bozulup bozulmadığını anlamak isteyen bir araştırmacı aşağıdaki verilerden hangisine öncelikle bakmalıdır?', 'Hanehalkı gelir anketlerinden elde edilen gelir grubu payları', ['Toplam ihracat rakamları', 'Merkez bankası rezervleri', 'Yıllık kişi başı elektrik tüketimi ve otomobil sayısı'], 'Gelir dağılımı, hanelerin gelirlerini ve bu gelirlerin gruplar arasındaki paylaşımını ölçen anketlerle izlenir; Türkiye\'de TÜİK\'in gelir ve yaşam koşulları araştırması bu amaçla yapılır.'),
  ('Dünya Bankası ülkeleri kişi başı milli gelire göre kaç gelir grubuna ayırır?', 'Dört', ['İki', 'Üç', 'Yedi'], 'Ülkeler düşük gelirli, alt-orta gelirli, üst-orta gelirli ve yüksek gelirli olmak üzere dört gruba ayrılır; eşik değerler her yıl güncellenir.'),
  ('Makroekonomide \'şok\' kavramı en iyi nasıl tanımlanır?', 'Ekonomiyi dengesinden uzaklaştıran beklenmedik bir olay', ['Her yıl aynı tarihte tekrarlanan bir bayram tatili', 'Hükümetin önceden duyurduğu ve herkesin bildiği bir karar', 'Fiyatların her zaman sabit kaldığı bir dönem'], 'Petrol fiyatlarındaki ani sıçrama, bir salgın ya da beklenmedik bir verimlilik artışı gibi olaylar talep ya da arz şoku olarak sınıflanır.'),
  ('Bir ekonomide işsizlik oranı sabit kalırken her ay çok sayıda kişinin işe girip çok sayıda kişinin işini kaybetmesi neyi gösterir?', 'İşgücü piyasasında yoğun giriş ve çıkış akımları olduğunu', ['Hiç kimsenin iş değiştirmediğini', 'İstatistiklerin mutlaka hatalı olduğunu', 'İşsizlerin tamamının aynı kişiler olduğunu ve hiç değişmediğini'], 'Sabit bir oran, piyasanın durgun olduğu anlamına gelmez; işe girişler ile iş kayıpları birbirini dengeleyebilir.'),
  ('Bir ülkenin kişi başı GSYH\'si, kur değişiminden etkilenmemesi için hangi yöntemle uluslararası karşılaştırmaya daha uygun hâle getirilir?', 'Satın alma gücü paritesiyle dönüştürülerek', ['Cari piyasa kuruyla dönüştürülerek', 'Yalnızca yerel para birimiyle bırakılarak', 'Altın fiyatına bölünerek ve petrolle çarpılarak'], 'Piyasa kurları kısa dönemde sert dalgalanabilir ve fiyat düzeyi farklarını yansıtmaz. SAGP dönüşümü bu iki sorunu da azaltır.'),
  ('Bir ekonomist \'Ekonomi potansiyelinin altında çalışıyor\' dediğinde aşağıdakilerden hangisini kastetmiş olabilir?', 'İşsizliğin doğal oranın üzerinde olduğunu ve kapasitenin tam kullanılmadığını', ['Enflasyonun hızla yükseldiğini', 'Ücretlerin verimlilikten hızlı arttığını', 'Ekonominin aşırı ısındığını ve kapasitenin aşıldığını'], 'Negatif üretim açığı atıl kapasiteye ve işsizliğin doğal oranın üzerinde olmasına karşılık gelir; bu dönemde enflasyon baskısı genellikle zayıftır.'),
  ('İngilizce \'output gap\' kavramının Türkçedeki karşılığı ve anlamı hangisidir?', 'Üretim açığı; gerçekleşen üretim ile potansiyel üretim arasındaki fark', ['Dış ticaret açığı; ihracat ile ithalat arasındaki fark', 'Bütçe açığı; kamu gelirleri ile giderleri arasındaki fark', 'Tasarruf açığı; tasarruf ile tüketim arasındaki fark'], 'Üretim açığı, ekonominin kapasitesinin üzerinde mi altında mı çalıştığını gösterir ve potansiyel üretime oranla yüzde olarak ifade edilir.'),
  ('Toplam talep eğrisi, fiyat düzeyi ile talep edilen toplam üretim arasında nasıl bir ilişki gösterir?', 'Ters yönlü (negatif eğimli) bir ilişki', ['Aynı yönlü (pozitif eğimli) bir ilişki', 'Hiçbir ilişki göstermez, eğri tamamen dikeydir', 'Yalnızca fiyatlar sıfırken tanımlı bir ilişki'], 'Fiyat düzeyi düştükçe servet, faiz ve dış ticaret etkileri nedeniyle talep edilen toplam mal ve hizmet miktarı artar.'),
  ('Bir konjonktür dalgasının bir tepe noktasından bir sonraki tepe noktasına kadar geçen süreye ne ad verilir?', 'Dalganın süresi', ['Dalganın genliği', 'Dalganın derinliği', 'Dalganın eğimi ve hızı'], 'Konjonktür dalgasının süresi ardışık iki tepe ya da iki dip arasındaki zamandır. Genlik ise dalgalanmanın şiddetini, yani tepe ile dip arasındaki farkı gösterir.'),
  ('Bir ülkede \'ekonomik canlanma\' döneminde aşağıdakilerden hangisinin gerçekleşmesi beklenir?', 'Firmaların yeniden işçi almaya başlaması', ['İflasların hızla artması', 'Stokların planlanmadan birikmesi', 'Tüketicilerin harcamalarını sürekli kısması ve güvenin çökmesi'], 'Dip noktasından sonra talep toparlandıkça firmalar üretimi artırır ve önce çalışma saatlerini, ardından istihdamı yükseltir.'),
  ('Siyasi istikrarsızlığın ve sık hükümet değişikliklerinin uzun dönem ekonomik büyümeyi zayıflatmasının temel yolu hangisidir?', 'Belirsizliği artırarak yatırımları caydırması', ['Nüfusu hızla artırması', 'Teknolojiyi kendiliğinden ilerletmesi', 'Tasarrufları zorunlu olarak artırması ve faizleri sıfırlaması'], 'Kuralların ve politikaların sık değişeceği beklentisi, uzun vadeli projelerin getirisini belirsizleştirir; girişimciler yatırımı erteler ya da sermayelerini başka ülkelere taşır.'),
  ('Kreş ve çocuk bakım hizmetlerinin yaygınlaşması kadınların işgücüne katılımını nasıl etkiler?', 'Artırır, çünkü bakım yükü nedeniyle çalışamayanların işgücüne girmesini kolaylaştırır', ['Azaltır, çünkü bakım hizmetleri iş olanaklarını yok eder', 'Hiç etkilemez', 'Yalnızca erkeklerin işgücüne katılımını değiştirir, kadınları etkilemez'], 'Türkiye\'de işgücü dışındaki kadınların önemli bir kısmı ev işleri ve bakım sorumluluğunu neden olarak gösterir; erişilebilir bakım hizmetleri bu engeli azaltır.'),
  ('Kalkınma sürecinde kentte yaşayan nüfusun payının artmasının ekonomik açıdan en önemli nedeni hangisidir?', 'Kentlerde sanayi ve hizmet sektörlerinde daha verimli ve yüksek gelirli işlerin bulunması', ['Kentlerde hiç iş olmaması', 'Kırsal nüfusun yasayla kentlere taşınmak zorunda bırakılması', 'Kentlerde yaşam maliyetinin her zaman kırsaldan düşük olması ve konutların ücretsiz verilmesi'], 'Kalkınmayla birlikte iş olanakları tarımdan sanayi ve hizmetlere kayar; bu sektörlerin kentlerde yoğunlaşması iç göçü ve kentleşmeyi hızlandırır.'),
  ('Mevsimsel dalgalanmalar ile konjonktür dalgalanmaları arasındaki temel fark hangisidir?', 'Mevsimsel olanlar her yıl benzer biçimde tekrarlanır; konjonktürel olanlar birkaç yıla yayılır ve düzensizdir', ['Mevsimsel dalgalanmalar yalnızca sanayide, konjonktür dalgaları yalnızca tarımda görülür', 'İkisi aynı olgunun farklı adlarıdır', 'Konjonktür dalgaları yalnızca bir gün sürer, mevsimsel dalgalar on yıllarca devam eder'], 'Bayramlar ve hava koşulları gibi etkenler yıl içinde öngörülebilir dalgalanmalar yaratır; konjonktür ise ekonominin genelinde birkaç yıla yayılan genişleme ve daralmalardır.'),
  ('Yolsuzluğun yaygın olduğu ülkelerde yatırımların ve büyümenin zayıf kalmasının en doğrudan nedeni hangisidir?', 'İş yapmanın maliyetinin ve belirsizliğin artması', ['Vergilerin tamamen kaldırılması', 'Bütün yatırımların kamu tarafından yapılması', 'Kayıt dışılığın tamamen ortadan kalkması'], 'Rüşvet, girişimciler için öngörülemeyen bir vergi gibi işler; ayrıca kaynakların en verimli projelere değil, bağlantıları güçlü olanlara gitmesine yol açar.'),
  ('TÜİK işgücü istatistiklerinde istihdam edilenler \'işteki durum\'a göre sınıflanır. Aşağıdakilerden hangisi bu sınıflardan biri değildir?', 'Emekli', ['Ücretli, maaşlı ya da yevmiyeli', 'İşveren', 'Kendi hesabına çalışan'], 'İşteki durum kategorileri ücretli-maaşlı-yevmiyeli, işveren, kendi hesabına çalışan ve ücretsiz aile işçisidir. Çalışmayan bir emekli istihdamda olmadığından bu sınıflamaya girmez.'),
  ('Makroekonomik politikanın genel olarak kabul gören temel hedefleri arasında aşağıdakilerden hangisi yer almaz?', 'Bütün malların fiyatlarını eşitlemek', ['İstikrarlı ekonomik büyüme', 'Yüksek istihdam', 'Fiyat istikrarı'], 'Makroekonomik politikalar sürdürülebilir büyüme, yüksek istihdam, fiyat istikrarı ve dış dengeyi hedefler. Malların göreli fiyatları ise piyasada arz ve talebe göre oluşur.'),
  ('Bir ülkede ortalama yaşam süresinin uzamasıyla insanların daha sağlıklı ve uzun yaşaması GSYH\'de doğrudan nasıl görünür?', 'Doğrudan görünmez; GSYH yaşam süresini ölçmez', ['GSYH\'ye her ek yıl için sabit bir tutar eklenir', 'GSYH\'den düşülür', 'Yalnızca ithalat kaleminde görünür'], 'GSYH piyasa üretimini ölçer. Sağlıklı yaşam süresindeki artış refahın önemli bir parçası olsa da doğrudan hesaba girmez; bu yüzden İnsani Gelişme Endeksi gibi ölçütler kullanılır.'),
  ('İşsizlik sigortasının ve sosyal yardımların bulunmadığı bir ülkede işsizliğin bireysel maliyeti nasıl değişir?', 'Daha da ağırlaşır; gelir kaybı tamamen hanenin üzerinde kalır', ['Ortadan kalkar', 'Hiç değişmez', 'Devlet bütçesine tamamen aktarılır ve hane etkilenmez'], 'Sosyal koruma mekanizmaları gelir kaybının bir kısmını toplumla paylaşır. Bunlar yoksa haneler birikimlerini tüketmek, borçlanmak ya da zorunlu harcamaları kısmak zorunda kalır.'),
  ('Bir ülkede yüksek işsizliğin uzun süre devam etmesinin toplumsal maliyetleri arasında aşağıdakilerden hangisi sayılabilir?', 'Gençlerin göç etmesi ve toplumsal huzursuzluğun artması', ['Vergi gelirlerinin kendiliğinden artması', 'Beceri düzeyinin hızla yükselmesi', 'Gelir dağılımının kendiliğinden düzelmesi'], 'Uzun süreli işsizlik yoksulluğu derinleştirir, nitelikli gençleri göçe yöneltebilir ve kurumlara olan güveni zayıflatabilir.'),
  ('Bir ekonomide yatırımların finanse edilebilmesi için uzun dönemde temel kaynak hangisidir?', 'Hanehalkı, firma ve kamu kesiminin tasarrufları', ['Merkez bankasının sınırsız para basması', 'Stokların sürekli eritilmesi', 'Ücretlerin her yıl düşürülmesi ve tüketimin yasaklanması'], 'Bir ekonominin yatırımı, kendi tasarrufları ile yurt dışından sağladığı tasarrufların toplamını aşamaz; bu nedenle tasarruf sermaye birikiminin kaynağıdır.'),
  ('Okun yasası açısından bir ülkede işsizlik oranının düşük kalabilmesi için ekonominin hangi koşulu sağlaması gerekir?', 'En az potansiyel büyüme hızında büyümesi', ['Hiç büyümemesi', 'Fiyatların sürekli düşmesi', 'Nüfusun hızla azalması ve işgücünün küçülmesi'], 'İşgücü ve verimlilik her yıl artar. Ekonomi bu artışı karşılayacak hızda büyümezse yeni katılanlar iş bulamaz ve işsizlik yükselir.'),
  ('Ekonomi gazetelerinde \'yumuşak iniş\' ve \'sert iniş\' tartışmaları en çok hangi durumda gündeme gelir?', 'Hızlı büyüyen ya da ısınmış bir ekonominin yavaşlamaya başladığı dönemlerde', ['Ekonominin derin bir resesyonun dibinde olduğu dönemlerde', 'Bir ülkenin yeni para birimine geçtiği gün', 'Nüfus sayımı sonuçlarının açıklandığı dönemlerde ve seçimlerde'], 'Bu kavramlar, enflasyonu düşürmek ya da aşırı ısınmayı gidermek amacıyla yavaşlayan bir ekonominin resesyona girip girmeyeceği sorusuyla ilgilidir.'),
  ('Bir ülkede 4 milyon işsizin 1 milyonu bir yıldan uzun süredir iş aramaktadır. Uzun süreli işsizlerin toplam işsizler içindeki payı yüzde kaçtır?', '25', ['4', '40', '75'], 'Uzun süreli işsizlik payı = 1 / 4 = 0,25, yani yüzde 25\'tir.'),
  ('Bir ülkenin genel refah düzeyini değerlendirmek için en kapsamlı yaklaşım hangisidir?', 'Gelir, sağlık, eğitim, eşitsizlik ve çevre göstergelerini birlikte değerlendirmek', ['Yalnızca toplam nominal GSYH\'ye bakmak', 'Yalnızca borsa endeksine bakmak', 'Yalnızca nüfus büyüklüğüne bakmak ve diğer verileri dışarıda bırakmak'], 'Her göstergenin sınırlılıkları vardır; refahın çok boyutlu yapısı ancak birden fazla göstergenin birlikte incelenmesiyle anlaşılabilir.'),
  ('Bir ülkenin GSYH\'sinin yüksek olmasına karşın kişi başı GSYH\'sinin düşük olması en çok neyi gösterir?', 'Ekonominin büyük, fakat nüfusa göre ortalama üretimin düşük olduğunu', ['Ülkenin nüfusunun çok az olduğunu', 'Ülkede hiç ithalat yapılmadığını', 'Fiyatların sürekli düştüğünü'], 'Büyük nüfuslu ülkeler toplamda çok üretebilir; ancak bu üretim kalabalık bir nüfusa bölündüğünde kişi başına düşen miktar düşük kalabilir.'),
];
